    r=by[p]; return '%s %-16s %-28s %10s'%(p,r['full_name'],r['compensation_reason'] or '-- NO CLAIM --',r['direct_payment_usd'])
import sys
for c in ['PAT_265','PAT_033','PAT_006']:
    print('#'*70); print('CLAIMANT',desc(c))
    seen={c}
    # 2-hop neighborhood both directions
    frontier=[c]
    for depth in (1,2):
        nxt=[]
        for n in frontier:
            outn=by[n]['emergency_contact_patient_id']
            for m,lbl in [(outn,'OUT')]+[(x,'IN') for x in inc[n]]:
                if m in seen: continue
                seen.add(m); nxt.append(m)
                print('  d%d %s %s  (via %s)'%(depth,lbl,desc(m),n))
        frontier=nxt
